// ── A3c 期望薪资：选择行 + 共用薪资区间层（bottom-drawer 统一 Task 5）─────────
// 原页面自写的 薪资轮/档表/算法 已整体移除：档表与 动态上限 纯函数迁到
// 组件/引导薪资档位（页面不被共用组件反向依赖），滚轮正文归 薪资区间层
// （用途='求职引导'）。本行按项目选择行视觉显示「面议」或区间，点开抽屉；
// 确定才调用两侧 setter，取消 / 遮罩 / Escape 不回填。

function 薪资题({
  下限,
  设下限,
  上限,
  设上限,
  单位,
}: {
  下限: number;
  设下限: (档: number) => void;
  上限: number;
  设上限: (档: number) => void;
  单位: 求职薪资单位;
}) {
  const 是日薪 = 单位 === '元/天';
  const [层开, 设层开] = useState(false);
  // 行上只显示回显值：面议 或区间。单位是显示后缀（/天），数据单位仍是 求职薪资单位
  const 行文字 = 下限 === 0 ? '面议' : `${下限}-${上限}${是日薪 ? '/天' : 'K'}`;
  return (
    <滚动区 样式覆盖={{ padding: '12px 18px 10px' }}>
      <页面大标题 标题={是日薪 ? '期望实习日薪是？' : '期望现金月薪是？'} />

      <表单条目
        标签={`薪资要求（${是日薪 ? '日薪 · 元/天' : '月薪 · K'}）`}
        值={行文字}
        按下={() => 设层开(true)}
      />

      {层开 ? (
        <薪资区间层
          用途="求职引导"
          周期={是日薪 ? 'day' : 'month'}
          下限={下限}
          上限={上限}
          确认={(下, 上) => {
            设下限(下);
            设上限(上);
            设层开(false);
          }}
          取消={() => 设层开(false)}
        />
      ) : null}
    </滚动区>
  );
}

// ── A3e 硬性排除 ─────────────────────────────────────────────
const 排除候选 = ['大小周', '纯外包 / 乙方', '全现场办公', '频繁出差'];

/** 一键补选提示：存在未关联公司文本时先回工作经历补齐选择，本轮不静默部分执行。 */
const 需补齐经历文案 = '有工作经历还没选择公司，请先到工作经历补选后重试';
/** 一键无可屏蔽目标的提示：无目标不能显示全部已屏蔽。 */
const 无可屏蔽文案 = '简历里还没有可一键屏蔽的公司';

function 排除题({ 已选, 切换, 提交自定义 }: {
  已选: string[];
  切换: (项: string) => void;
  提交自定义: (词: string) => void;
}) {
  const { 状态: 全局, 数据源模式, 操作, 后端状态 } = use应用状态();
  const { 跳转 } = use导航();
  const 是后端 = 数据源模式 === 'backend';
  // 学生分流：实习公司通常不必屏蔽，一键开关默认关；社会人现雇主本来就该挡，默认开
  const 在校生 = 全局.基本信息.身份 === '在校';
  // 简历里出现过的公司（含现雇主）：Mock 一键屏蔽的来源
  const 简历里的公司 = useMemo(
    () => [...new Set(全局.简历经历.map((条) => 条.公司).filter(Boolean))],
    [全局.简历经历]
  );
  // J-PILOT-02 Task 7（Spec §3.4 / §5.2）：Backend 的屏蔽状态只能来自权威隐私快照 ——
  // 简历里的公司名只是文字，既不默认显示成已屏蔽，也不能因社招身份自动写入。
  // 2026-09-13 合同 A/B（Task 5）：「再加一家」改走公司选择抽屉，选中/添加完成即以
  // source=手动添加 屏蔽；一键屏蔽按真实组织 ID 顺序写（见 一键屏蔽后端）。
  const 权威屏蔽: 屏蔽项[] = 是后端 ? 全局.屏蔽名单 : [];
  const [一键屏蔽简历公司, 设一键屏蔽简历公司] = useState(是后端 ? false : !在校生);
  const [屏蔽公司, 设屏蔽公司] = useState<string[]>(是后端 || 在校生 ? [] : 简历里的公司);
  const [公司录入中, 设公司录入中] = useState(false);
  const [公司草稿, 设公司草稿] = useState('');
  // 解除在途：沿用现有禁用承载，不新增控件；成功与否一律以权威快照为准
  const [解除中, 设解除中] = useState<string | null>(null);
  // 合同 B：公司选择抽屉（再加一家）。关闭先 作废 在飞搜索/创建。
  const [抽屉开, 设抽屉开] = useState(false);
  const 查询 = use组织查询({
    搜索: 是后端 ? 操作?.搜索组织 : undefined,
    创建: 是后端 ? 操作?.创建组织 : undefined,
    作用域键: JSON.stringify([数据源模式, 后端状态?.主体?.subject_id ?? null, '引导问答屏蔽']),
  });

  const 提交公司 = () => {
    // Backend 的「再加一家」走公司选择抽屉（真实组织 ID），行内自由文本只在 Mock 演示
    const 名 = 公司草稿.trim();
    if (名 !== '' && !屏蔽公司.includes(名)) 设屏蔽公司((旧) => [...旧, 名]);
    设公司草稿('');
    设公司录入中(false);
  };

  /** 一键目标（Backend）：非空公司经历按真实组织 ID 去重；同 ID 多条只调一次、在职优先；
   *  结束时间为 null 的在职经历用 当前雇主，其余曾任职企业用手动添加 ——
   *  绝不从历史经历推断 关联公司。 */
  const 一键目标 = useMemo(() => {
    const 表 = new Map<string, 屏蔽来源>();
    for (const 条 of 全局.简历经历) {
      if (条.公司.trim() === '' || 条.组织编号 === undefined) continue;
      const 源: 屏蔽来源 = 条.结束 === null ? '当前雇主' : '手动添加';
      const 既有 = 表.get(条.组织编号);
      if (既有 === undefined || (既有 !== '当前雇主' && 源 === '当前雇主')) {
        表.set(条.组织编号, 源);
      }
    }
    return [...表.entries()].map(([组织编号, 源]) => ({ 组织编号, 源 }));
  }, [全局.简历经历]);
  // 先检查所有非空公司经历都有组织编号：缺任一则本轮整组不执行
  const 缺编号 = 全局.简历经历.some((条) => 条.公司.trim() !== '' && 条.组织编号 === undefined);
  /** 开关状态从本次目标集合与权威屏蔽计算：全部目标已在名单才亮，无目标恒关。 */
  const 一键开 = 一键目标.length > 0 &&
    一键目标.every((目标) => 权威屏蔽.some((块) => 块.组织编号 === 目标.组织编号));
  const [一键进行中, 设一键进行中] = useState(false);
  // 一键 与 手动（抽屉选定/添加）两条入口共用同一同步写入锁：任一在途时另一入口直接挡下
  // —— 否则操作层对相同在途键的重复提交会被静默吞掉，手动入口把未执行的调用当成功关抽屉
  const 屏蔽写入中 = useRef(false);

  /** Backend 一键屏蔽：顺序 await（不用 Promise.all）；已有屏蔽不改 source；
   *  首次失败停止剩余写入 —— 已成功项随权威快照展示，重试时权威名单已含的编号被跳过。
   *  关闭只导航现有屏蔽名单做逐项解除确认（当前雇主/关联公司不能由一键绕过），不做假的本地关态。 */
  const 一键屏蔽后端 = async () => {
    if (一键开) {
      跳转(路径.屏蔽名单);
      return;
    }
    if (缺编号) {
      轻提示(需补齐经历文案);
      return;
    }
    if (一键目标.length === 0) {
      轻提示(无可屏蔽文案);
      return;
    }
    if (一键进行中 || 屏蔽写入中.current) return;
    屏蔽写入中.current = true;
    设一键进行中(true);
    try {
      for (const 目标 of 一键目标) {
        if (权威屏蔽.some((块) => 块.组织编号 === 目标.组织编号)) continue;
        await 操作.添加组织屏蔽(目标.组织编号, 目标.源);
      }
    } catch (错误) {
      轻提示(取后端错误文案(错误));
    } finally {
      屏蔽写入中.current = false;
      设一键进行中(false);
    }
  };

  const 切一键屏蔽 = () => {
    if (是后端) {
      void 一键屏蔽后端();
      return;
    }
    const 新值 = !一键屏蔽简历公司;
    设一键屏蔽简历公司(新值);
    设屏蔽公司((旧) =>
      新值
        ? [...new Set([...旧, ...简历里的公司])]
        : 旧.filter((名) => !简历里的公司.includes(名))
    );
  };

  /** 选中/添加完成即执行该明确的添加屏蔽动作（source=手动添加），成功才由权威快照出 chip。
   *  在途重入挡下（与 一键屏蔽后端 共用 屏蔽写入中 同步引用）：操作层对相同在途键的
   *  重复提交会被背刺防护吞掉，不能把未执行的调用当成功关抽屉。屏蔽失败只提示错误、
   *  不再次造目录条目：抽屉保持打开，用户可重选同一企业重试。 */
  const 屏蔽选中企业 = async (项: BFF组织搜索项) => {
    if (屏蔽写入中.current) return;
    屏蔽写入中.current = true;
    try {
      await 操作.添加组织屏蔽(项.organization_id, '手动添加');
    } catch (错误) {
      轻提示(取后端错误文案(错误));
      return;
    } finally {
      屏蔽写入中.current = false;
    }
    查询.作废();
    设抽屉开(false);
  };
  const 选定公司键 = (键: string) => {
    // 选中 ID 只来自本实例结果：同名不同 ID 不混淆
    const 项 = 查询.结果.find((候选) => 候选.organization_id === 键);
    if (项) void 屏蔽选中企业(项);
  };
  const 添加公司 = async (名称: string) => {
    const 项 = await 查询.添加(名称);
    if (!项) return; // 创建失败/在飞/被作废：错误已由抽屉 创建错误 展示，不重造条目
    await 屏蔽选中企业(项);
  };
  const 关闭抽屉 = () => {
    查询.作废();
    设抽屉开(false);
  };

  /** Backend 解除：成功才由权威快照撤掉 chip；失败保留原状并复用既有轻提示报错。
   *  只对 手动添加 开放单击直解 —— 建档时自动加入的当前雇主/关联公司按 Spec §5.2
   *  必须先过风险确认，本屏没有那层确认（也不新增），所以在这里只说明、不代用户确认。 */
  const 解除屏蔽 = async (条: 屏蔽项) => {
    if (条.来源 !== '手动添加') {
      轻提示('当前雇主 / 关联公司的屏蔽需要风险确认，请到屏蔽名单页解除');
      return;
    }
    设解除中(条.组织编号);
    try {
      // 传完整条目：操作层按 条目.来源 推导是否需要风险确认（与 屏蔽名单 屏同一规则）
      await 操作.解除组织屏蔽(条);
    } catch (错误) {
      轻提示(取后端错误文案(错误));
    } finally {
      设解除中(null);
    }
  };

  // 两模式共用同一枚 chip 的展示与位置，只有来源与「点掉」的含义不同
  const 屏蔽标签们 = 是后端
    ? 权威屏蔽.map((条) => ({
        键: 条.组织编号,
        文字: 条.名称,
        禁用: 解除中 === 条.组织编号,
        按下: () => { void 解除屏蔽(条); },
      }))
    : 屏蔽公司.map((名) => ({
        键: 名,
        文字: 名,
        禁用: false,
        按下: () => 设屏蔽公司((旧) => 旧.filter((条) => 条 !== 名)),
      }));

  return (
    <滚动区 样式覆盖={{ paddingBottom: 12 }}>
      <页面大标题 标题="哪些情况直接排除？" />

      <div className={样式.排除区}>
        <排除选项 已选={已选} 切换={切换} 提交自定义={提交自定义} />

        <div className={样式.屏蔽公司卡}>
          <div className={样式.屏蔽公司头}>
            <div>
              <div className={样式.屏蔽公司标题}>屏蔽公司</div>
              <div className={样式.屏蔽公司说明}>简历里出现过的公司</div>
            </div>
            {/* 标注 11:58：改成一键开关 —— 简历里的公司一次性全屏蔽。
                Backend 开关状态从目标集合与权威屏蔽计算：全成功才亮，关闭只去屏蔽名单逐项确认 */}
            <开关
              标签="一键屏蔽简历中的公司"
              开={是后端 ? 一键开 : 一键屏蔽简历公司}
              切换={切一键屏蔽}
              禁用={是后端 ? 一键进行中 : false}
            />
          </div>

          {/* Backend 的再加一家走公司选择抽屉（真实组织 ID）；Mock 保持行内自由文本演示 */}
          <button
            className={`${样式.屏蔽公司添加} 可点`}
            onClick={() => (是后端 ? 设抽屉开(true) : 设公司录入中(true))}
          >
            ＋ 再加一家
          </button>

          {公司录入中 ? (
            <行内输入
              占位="公司名，可只写关键词"
              值={公司草稿}
              改变={设公司草稿}
              提交={提交公司}
            />
          ) : null}

          {是后端 && 抽屉开 ? (
            <公司选择抽屉接线
              查询={查询}
              选中键={null}
              选定={选定公司键}
              关闭={关闭抽屉}
              添加={(名称) => void 添加公司(名称)}
            />
          ) : null}

          {屏蔽标签们.length > 0 ? (
            <div className={样式.屏蔽公司标签组}>
              {屏蔽标签们.map((条) => (
                <button
                  key={条.键}
                  className={`${样式.已选标签} 可点`}
                  disabled={条.禁用}
                  onClick={条.按下}
                >
                  {条.文字} ✕
                </button>
              ))}
            </div>
          ) : null}
        </div>
      </div>
    </滚动区>
  );
}

// ──「到岗节奏」题（原 A3f）已整体挪去 求职状态 屏 /onboard/status ──

// ── A3g 个人优势（备忘录式编辑 + GitHub）──────────────────────

function 优势题({ 文本, 设文本, 说明, 恢复文案, 恢复 }: {
  文本: string;
  设文本: (值: string) => void;
  /** 副标说明只在注册流给（“已根据你上传的简历预先提取…”）；
      个人优势编辑入口（Task 4）不传 —— 初值是用户已存文本，与解析建议无关 */
  说明?: string;
  恢复文案: string;
  /** null = 无可恢复来源（Backend 无当前轮真实建议 / 编辑场景），整行不渲染 */
  恢复: (() => void) | null;
}) {

  return (
    <滚动区 样式覆盖={{ paddingBottom: 12 }}>
      <页面大标题
        标题="分享一下自己的个人优势"
        说明={说明}
      />

      <div className={样式.优势卡}>
        <textarea
          className={样式.优势输入}
          value={文本}
          onChange={(事件) => 设文本(事件.target.value)}
          maxLength={500}
          aria-label="个人优势"
        />
        <div className={样式.优势底}>
          <span className={样式.优势提示}>✕ 删除一行：长按段落</span>
          <span className={`${样式.优势计数} 等宽数字`}>{文本.length} / 500</span>
        </div>
      </div>

      {/* 指向「工作经历」页的专业技能区块。这里只指路、不再复制一套标签编辑器：
          一是技能只该有一个写入口，二是本屏答案存在内存里，中途跳走会全丢。
          技能必须是标签而不是这段自由文本（标注 13:18 指路小字删）。 */}
      {/* 与 工作经历 屏的「作品集或项目链接」区块共用同一个简历字段，任一入口修改都立即持久化。 */}
        {/* GitHub/作品集链接行按标注 2026-08-24 挪走 ——
            同一字段在「在线简历」屏的 作品集或项目链接 小节（作品集下方），
            这里不再重复出现 */}

      {/* 恢复 = 把编辑框写回真实来源：Mock 是原型种子文本；Backend 是当前轮服务端建议。
          Backend 无可用建议时（恢复 === null）整行不出现，不虚构「可恢复」的假动作 */}
      {恢复 ? (
        <div className={样式.优势工具行}>
          <button className={`${样式.优势工具主} 可点`} onClick={恢复}>
            ◈ {恢复文案}
          </button>
        </div>
      ) : null}

    </滚动区>
  );
}

// ── 搜索条（期望职位 / 工作城市 共用，可真实输入并过滤）─────────
function 搜索条({
  占位,
  值,
  改变,
}: {
  自动聚焦?: boolean;
  占位: string;
  值: string;
  改变: (文本: string) => void;
}) {
  return (
    <div className={样式.搜索条}>
      <放大镜图标 尺寸={15} 色="var(--最弱)" 线宽={2.2} />
      <input
        className={样式.搜索输入}
        placeholder={占位}
        value={值}
        onChange={(事件) => 改变(事件.target.value)}
      />
    </div>
  );
}

// ── 底部已选条（点标签 ✕ 移除）───────────────────────────────
function 已选条({ 条目们, 移除 }: { 条目们: 已选条目[]; 移除: (键: string) => void }) {
  return (
    <div className={样式.已选条}>
      <span className={样式.已选标}>已选</span>
      <div className={样式.已选标签组}>
        {条目们.map((条) => (
          <button
            key={条.键}
            className={`${样式.已选标签} 可点`}
            onClick={() => 移除(条.键)}
          >
            {条.文字} ✕
          </button>
        ))}
      </div>
    </div>
  );
}

// ── 行内录入行（自定义排除条件 / 屏蔽公司 共用）────────────────
function 行内输入({
  自动聚焦 = true,
  占位,
  值,
  改变,
  提交,
}: {
  自动聚焦?: boolean;
  占位: string;
  值: string;
  改变: (文本: string) => void;
  提交: () => void;
}) {
  return (
    <div className={样式.行内输入行}>
      <input
        className={样式.行内输入}
        placeholder={占位}
        value={值}
        onChange={(事件) => 改变(事件.target.value)}
        onKeyDown={(事件) => {
          if (事件.key === 'Enter') 提交();
        }}
        enterKeyHint="done"
        autoFocus={自动聚焦}
      />
      <button className={`${样式.行内确认} 可点`} onClick={提交}>
        添加
      </button>
    </div>
  );
}

/** 新增意向与首次引导共享原有两列排除项和常驻行内输入。
 *  提交自定义 缺省即 切换：日常新增意向仍是单一载体（网格与输入同进 已选），行为不变；
 *  首次引导传入自己的写入口，让行内输入的原话进 自定义诉求 而不是按名字当成卡片。 */
export function 排除选项({ 已选, 切换, 自动聚焦 = true, 提交自定义: 写自定义 = 切换 }: {
  已选: string[];
  切换: (项: string) => void;
  自动聚焦?: boolean;
  提交自定义?: (词: string) => void;
}) {
  const [自定义草稿, 设自定义草稿] = useState('');
  // 用户自己写的排除条件也进同一个网格，写完即视为已选
  const 全部候选 = [...排除候选, ...已选.filter((项) => !排除候选.includes(项))];

  const 提交自定义 = () => {
    const 词 = 自定义草稿.trim();
    if (词 !== '' && !已选.includes(词)) 写自定义(词);
    设自定义草稿('');
  };

  return <>
        <div className={样式.排除网格}>
          {全部候选.map((项) => {
            const 选中 = 已选.includes(项);
            return (
              <button
                key={项}
                className={`${样式.排除键} ${选中 ? 样式.排除键选中 : ''} 可点`}
                onClick={() => 切换(项)}
              >
                {/* 2026-08-24 全站选择风格统一（C1 定稿）：✓ 改由 CSS ::before 前置渲染，去掉文字尾缀避免双勾 */}
                {项}
              </button>
            );
          })}
        </div>

        {/* 标注 2026-08-20 13:06/13:18：输入框常驻，小字引导写不喜欢的工作偏好 */}
        <div className={样式.自定义标}>自定义 · 写下你不喜欢的工作偏好，AI代理筛选时帮你挡掉</div>
        <行内输入
          自动聚焦={自动聚焦}
          占位="用你自己的话写"
          值={自定义草稿}
          改变={设自定义草稿}
          提交={提交自定义}
        />

  </>;
}
